using System.Buffers.Binary;
using System.Security.Cryptography;
using System.Text;
using DotJpegli.Internal;
using Xunit;
using static DotJpegli.Tests.EncoderProgressiveTests;

namespace DotJpegli.Tests;

public sealed class SrgbGrayscaleIccProfileTests
{
    // Independently generated by an MSVC C++17 /fp:strict /O2 probe calling
    // MaybeCreateProfile from the unchanged lib/cms/jpegli_cms_internal.h at
    // google/jpegli 031a0077f5799a6041004267fc12b956c1f52a20, with GRAY,
    // D65 white, the sRGB transfer function and perceptual rendering intent.
    private const string NativeSha256 = "BD99A693D2BA41BA6C0E818B2D7EE2B2A313289AD5B9C66FEFD54D09FFCA6406";
    private static readonly byte[] OpaqueProfile = [0x01, 0x23, 0x45, 0x67];

    [Fact]
    public void MatchesTheCompletePinnedNativeProfile()
    {
        byte[] profile = JpegliIccProfiles.CreateSrgbGrayscaleProfile();
        Assert.Equal(328, profile.Length);
        Assert.Equal(NativeSha256, Convert.ToHexString(SHA256.HashData(profile)));
        Assert.Equal("57A702AE8C0F59013AAA9E549C8C5CDA", Convert.ToHexString(profile.AsSpan(84, 16)));
    }

    [Fact]
    public void EachCallOwnsItsMutableStorage()
    {
        byte[] first = JpegliIccProfiles.CreateSrgbGrayscaleProfile();
        byte[] second = JpegliIccProfiles.CreateSrgbGrayscaleProfile();
        Assert.NotSame(first, second);
        Assert.Equal(first, second);
        Array.Fill(first, (byte)0xdd);
        Assert.Equal(NativeSha256, Convert.ToHexString(SHA256.HashData(second)));
        Assert.Equal(second, JpegliIccProfiles.CreateSrgbGrayscaleProfile());
    }

    [Fact]
    public void HeaderAndAlignedTagsDescribeThePinnedGrayscaleDisplayProfile()
    {
        byte[] profile = JpegliIccProfiles.CreateSrgbGrayscaleProfile();
        Assert.Equal(profile.Length, Int32(profile, 0));
        Assert.Equal("jxl ", Signature(profile, 4));
        Assert.Equal(0x04400000, Int32(profile, 8));
        Assert.Equal("mntr", Signature(profile, 12));
        Assert.Equal("GRAY", Signature(profile, 16));
        Assert.Equal("XYZ ", Signature(profile, 20));
        Assert.Equal(new[] { 2019, 12, 1, 0, 0, 0 },
            Enumerable.Range(0, 6).Select(index => UInt16(profile, 24 + index * 2)));
        Assert.Equal("acsp", Signature(profile, 36));
        Assert.Equal("APPL", Signature(profile, 40));
        Assert.All(profile[44..64], value => Assert.Equal(0, value));
        Assert.Equal(0, Int32(profile, 64)); // Perceptual rendering intent.
        // The D50 PCS illuminant in the header is separate from media white.
        Assert.Equal(0x0000f6d6, Int32(profile, 68));
        Assert.Equal(0x00010000, Int32(profile, 72));
        Assert.Equal(0x0000d32d, Int32(profile, 76));
        Assert.Equal("jxl ", Signature(profile, 80));
        Assert.All(profile[100..128], value => Assert.Equal(0, value));

        Dictionary<string, Tag> tags = Tags(profile);
        Assert.Equal(new[] { "cprt", "desc", "kTRC", "wtpt" }, tags.Keys.Order());
        Assert.Equal("Gra_D65_Per_SRG", Text(profile, tags["desc"]));
        Assert.Equal("CC0", Text(profile, tags["cprt"]));
        Tag white = tags["wtpt"];
        Assert.Equal("XYZ ", Signature(profile, white.Offset));
        Assert.Equal(20, white.Length);
        // Upstream's GRAY branch retains its D65 media white without a chad tag.
        double[] d65 = [0.3127 / 0.3290, 1, (1 - 0.3127 - 0.3290) / 0.3290];
        for (int channel = 0; channel < d65.Length; channel++)
            AssertClose(d65[channel], Fixed(profile, white.Offset + 8 + channel * 4),
                0.5 / 65536, $"D65 media white channel {channel}");
        Assert.Equal(2, IccProfile.LookupTransferFunction(profile, TestContext.Current.CancellationToken));

        Tag curve = tags["kTRC"];
        Assert.Equal(32, curve.Length);
        Assert.Equal("para", Signature(profile, curve.Offset));
        Assert.Equal(3, UInt16(profile, curve.Offset + 8));
        Assert.Equal(0, UInt16(profile, curve.Offset + 10));
        double[] expected = [2.4, 1 / 1.055, 0.055 / 1.055, 1 / 12.92, 0.04045];
        for (int index = 0; index < expected.Length; index++)
            AssertClose(expected[index], Fixed(profile, curve.Offset + 12 + index * 4),
                0.5 / 65536, $"sRGB curve parameter {index}");
    }

    [Fact]
    public void ProfileIdIsTheIndependentIccMd5Digest()
    {
        byte[] profile = JpegliIccProfiles.CreateSrgbGrayscaleProfile();
        byte[] id = profile[84..100];
        Array.Clear(profile, 44, 4);
        Array.Clear(profile, 64, 4);
        Array.Clear(profile, 84, 16);
        Assert.Equal(id, MD5.HashData(profile));
    }

    [Fact]
    public void ParsedGrayCurveMatchesAnIndependentSrgbDecodingOracle()
    {
        byte[] profile = JpegliIccProfiles.CreateSrgbGrayscaleProfile();
        Tag curve = Tags(profile)["kTRC"];
        double threshold = Fixed(profile, curve.Offset + 28);
        double[] boundaries = [0, 0.001, 0.01, 0.04044999, 0.04045, 0.04045001,
            threshold - 1e-8, threshold, threshold + 1e-8, 0.0625, 0.25, 0.5, 0.75, 1];
        foreach (double value in Enumerable.Range(0, 256).Select(value => value / 255.0).Concat(boundaries))
        {
            double expected = value <= 0.04045
                ? value / 12.92 : Math.Pow((value + 0.055) / 1.055, 2.4);
            AssertClose(expected, EvaluateCurve(profile, curve, value), 0.00003,
                $"linear gray at encoded sRGB {value:R}");
        }
        Assert.Equal(0, EvaluateCurve(profile, curve, 0));
        AssertClose(1, EvaluateCurve(profile, curve, 1), 0.00003, "linear white");
    }

    [Theory]
    [InlineData(0, false, false, 0)]
    [InlineData(1, false, true, 0)]
    [InlineData(2, false, true, 2)]
    [InlineData(0, true, true, 2)]
    [InlineData(1, true, false, 0)]
    [InlineData(2, true, true, 0)]
    public void ExplicitProfileEmbedsExactBytesWithoutChangingGrayCodingOrInputStorage(
        int kind, bool converted, bool progressive, int refinement)
    {
        const int width = 19, height = 17;
        int components = converted ? 4 : 1, rowLength = width * components, stride = rowLength + 5;
        byte[] bytes = Enumerable.Repeat((byte)0xad, (height - 1) * stride + rowLength).ToArray();
        for (int y = 0; y < height; y++)
            for (int x = 0; x < width; x++)
                for (int channel = 0; channel < (converted ? 3 : 1); channel++)
                    bytes[y * stride + x * components + channel] = (byte)((x * 73 + y * 29 + channel * 61) % 256);
        Array pixels = kind switch
        {
            0 => bytes,
            1 => bytes.Select((value, index) => (ushort)Math.Clamp(value * 257 + index % 47 - 23, 0, 65535)).ToArray(),
            _ => bytes.Select((value, index) => index % stride >= rowLength || converted && index % stride % 4 == 3
                ? float.NaN : Math.Clamp(value / 255f + (index % 47 - 23) / 65535f, 0f, 1f)).ToArray()
        };
        Array originalPixels = (Array)pixels.Clone();
        PixelComponentLayout layout = converted ? PixelComponentLayout.Bgra : PixelComponentLayout.Gray;
        byte[] profile = JpegliIccProfiles.CreateSrgbGrayscaleProfile();
        byte[] backing = Enumerable.Repeat((byte)0x5b, profile.Length + 11).ToArray();
        profile.CopyTo(backing, 3);
        byte[] originalBacking = backing.ToArray();
        var options = new JpegliEncoderOptions
        {
            ColorSpace = JpegColorSpace.Grayscale, IccProfile = backing.AsMemory(3, profile.Length),
            InferCicpTransferFunctionFromIccProfile = true, Distance = 1.375f,
            SmoothingFactor = 37, Progressive = progressive,
            ProgressiveRefinementBits = refinement, RestartInterval = 2
        };
        byte[] actual = Encode(pixels, width, height, stride, layout, options);
        (byte[] embedded, byte[] coding) = ReadIccAndCoding(actual);
        Assert.Equal(profile, embedded);
        byte[] opaque = Encode(pixels, width, height, stride, layout,
            options with { IccProfile = OpaqueProfile, InferCicpTransferFunctionFromIccProfile = false });
        Assert.Equal(ReadIccAndCoding(opaque).Coding, coding);
        Assert.Equal(actual, Encode(pixels, width, height, stride, layout,
            options with { InferCicpTransferFunctionFromIccProfile = false }));
        if (!converted)
            Assert.Equal(actual, Encode(pixels, width, height, stride, layout,
                options with { ColorSpace = JpegColorSpace.Automatic }));
        // This independent entropy reader validates the grayscale component,
        // restart intervals and baseline or progressive/refinement scan script.
        JpegDocument document = JpegDocument.Read(actual, progressive, 2, refinement);
        Assert.Equal(width, document.Width);
        Assert.Equal(height, document.Height);
        Assert.Equal(1, Assert.Single(document.Components).Key);
        Assert.All(document.Scans.SelectMany(scan => scan.Selectors), selector => Assert.Equal(1, selector.Component));
        using var destination = new MemoryStream();
        using var output = new WriteOnlyStream(destination);
        Encode(output, pixels, width, height, stride, layout, options);
        Assert.Equal(actual, destination.ToArray());
        Assert.False(output.Closed);
        Assert.Equal(originalBacking, backing);
        Assert.Equal(originalPixels.Cast<object>(), pixels.Cast<object>());
    }

    private static Dictionary<string, Tag> Tags(byte[] profile)
    {
        int count = Int32(profile, 128), end = 132 + count * 12;
        Assert.Equal(4, count);
        var result = new Dictionary<string, Tag>();
        var extents = new HashSet<Tag>();
        for (int index = 0; index < count; index++)
        {
            int entry = 132 + index * 12;
            var tag = new Tag(Int32(profile, entry + 4), Int32(profile, entry + 8));
            Assert.Equal(0, tag.Offset % 4);
            Assert.InRange(tag.Offset, end, profile.Length - 8);
            Assert.InRange(tag.Length, 8, profile.Length - tag.Offset);
            Assert.Equal(0, Int32(profile, tag.Offset + 4));
            Assert.True(result.TryAdd(Signature(profile, entry), tag));
            Assert.True(extents.Add(tag)); // This profile has no shared payloads.
        }
        Tag[] ordered = extents.OrderBy(tag => tag.Offset).ToArray();
        Assert.Equal(end, ordered[0].Offset);
        for (int index = 1; index < ordered.Length; index++)
        {
            int previousEnd = ordered[index - 1].Offset + ordered[index - 1].Length;
            Assert.Equal((previousEnd + 3) & ~3, ordered[index].Offset);
            Assert.All(profile[previousEnd..ordered[index].Offset], value => Assert.Equal(0, value));
        }
        Assert.Equal(profile.Length, ordered[^1].Offset + ordered[^1].Length);
        return result;
    }

    private static string Text(byte[] profile, Tag tag)
    {
        Assert.Equal("mluc", Signature(profile, tag.Offset));
        Assert.Equal(1, Int32(profile, tag.Offset + 8));
        Assert.Equal(12, Int32(profile, tag.Offset + 12));
        Assert.Equal("enUS", Signature(profile, tag.Offset + 16));
        int length = Int32(profile, tag.Offset + 20), offset = Int32(profile, tag.Offset + 24);
        Assert.Equal(0, length % 2);
        Assert.InRange(offset, 28, tag.Length);
        Assert.InRange(length, 0, tag.Length - offset);
        Assert.All(profile[(tag.Offset + offset + length)..(tag.Offset + tag.Length)], value => Assert.Equal(0, value));
        return Encoding.BigEndianUnicode.GetString(profile, tag.Offset + offset, length);
    }

    private static double EvaluateCurve(byte[] profile, Tag curve, double value)
    {
        double gamma = Fixed(profile, curve.Offset + 12), a = Fixed(profile, curve.Offset + 16),
            b = Fixed(profile, curve.Offset + 20), c = Fixed(profile, curve.Offset + 24),
            threshold = Fixed(profile, curve.Offset + 28);
        return value >= threshold ? Math.Pow(a * value + b, gamma) : c * value;
    }

    private static (byte[] Icc, byte[] Coding) ReadIccAndCoding(byte[] jpeg)
    {
        Assert.Equal(new byte[] { 0xff, 0xd8 }, jpeg[..2]);
        using var coding = new MemoryStream();
        coding.Write(jpeg.AsSpan(0, 2));
        byte[]? profile = null;
        int offset = 2;
        while (jpeg[offset + 1] != 0xda)
        {
            Assert.Equal(0xff, jpeg[offset]);
            int length = UInt16(jpeg, offset + 2);
            Assert.InRange(length, 2, jpeg.Length - offset - 2);
            int end = offset + 2 + length;
            if (jpeg[offset + 1] == 0xe2)
            {
                Assert.Null(profile);
                Assert.True(jpeg.AsSpan(offset + 4, 12).SequenceEqual("ICC_PROFILE\0"u8));
                Assert.Equal(1, jpeg[offset + 16]);
                Assert.Equal(1, jpeg[offset + 17]);
                profile = jpeg[(offset + 18)..end];
            }
            else
                coding.Write(jpeg.AsSpan(offset, end - offset));
            offset = end;
        }
        coding.Write(jpeg.AsSpan(offset));
        Assert.NotNull(profile);
        return (profile, coding.ToArray());
    }

    private static byte[] Encode(Array source, int width, int height, int stride,
        PixelComponentLayout layout, JpegliEncoderOptions options) => source switch
    {
        byte[] bytes => JpegliEncoder.Encode(bytes, width, height, (PixelLayout)(int)layout,
            options, stride, TestContext.Current.CancellationToken),
        ushort[] words => JpegliEncoder.Encode(words, width, height, layout,
            options, stride, TestContext.Current.CancellationToken),
        _ => JpegliEncoder.Encode((float[])source, width, height, layout,
            options, stride, TestContext.Current.CancellationToken)
    };

    private static void Encode(Stream output, Array source, int width, int height, int stride,
        PixelComponentLayout layout, JpegliEncoderOptions options)
    {
        if (source is byte[] bytes)
            JpegliEncoder.Encode(output, bytes, width, height, (PixelLayout)(int)layout,
                options, stride, TestContext.Current.CancellationToken);
        else if (source is ushort[] words)
            JpegliEncoder.Encode(output, words, width, height, layout,
                options, stride, TestContext.Current.CancellationToken);
        else
            JpegliEncoder.Encode(output, (float[])source, width, height, layout,
                options, stride, TestContext.Current.CancellationToken);
    }

    private static int Int32(byte[] profile, int offset) => BinaryPrimitives.ReadInt32BigEndian(profile.AsSpan(offset, 4));
    private static int UInt16(byte[] profile, int offset) => BinaryPrimitives.ReadUInt16BigEndian(profile.AsSpan(offset, 2));
    private static double Fixed(byte[] profile, int offset) => Int32(profile, offset) / 65536.0;
    private static string Signature(byte[] profile, int offset) => Encoding.ASCII.GetString(profile, offset, 4);
    private sealed record Tag(int Offset, int Length);

    private static void AssertClose(double expected, double actual, double tolerance, string label) =>
        Assert.True(double.IsFinite(actual) && Math.Abs(expected - actual) <= tolerance,
            $"{label}: expected {expected:R}, actual {actual:R}, tolerance {tolerance:R}.");
}
